from pathlib import Path
import numpy as np
p=Path('/opt/VLABench/VLABench/assets/obj/meshes/containers/fridge/big_fridge/fridge_big/collision')
for group in sorted(p.iterdir()):
 if not group.is_dir(): continue
 pts=[]
 for f in group.glob('*.obj'):
  for line in f.open(errors='ignore'):
   if line.startswith('v '):
    try: pts.append([float(x) for x in line.split()[1:4]])
    except: pass
 a=np.asarray(pts)
 print(group.name,'verts',len(a),'min',a.min(0).round(3),'max',a.max(0).round(3))
